const funnelRaw = $node['Fetch 24h Funnel Events'].json.data || [];
const ordersRaw = $node['Fetch 24h Orders'].json.data || [];

// Parse funnel events
const events = funnelRaw.map(e => e.attributes || e);
const orders = ordersRaw.map(o => o.attributes || o);

// 1. Channel conversion rates
const channelStats = {};
events.forEach(e => {
  const ch = e.channel || 'unknown';
  if (!channelStats[ch]) channelStats[ch] = { views: 0, clicks: 0, orders: 0, sessions: new Set() };
  channelStats[ch].sessions.add(e.session_id);
  if (e.event_type === 'view' || e.event_type === 'page_view') channelStats[ch].views++;
  if (e.event_type === 'click' || e.event_type === 'add_to_cart') channelStats[ch].clicks++;
  if (e.event_type === 'order_confirmed' || e.event_type === 'purchase') channelStats[ch].orders++;
});

const channelConversion = Object.entries(channelStats).map(([ch, s]) => ({
  channel: ch,
  unique_sessions: s.sessions.size,
  views: s.views,
  clicks: s.clicks,
  orders: s.orders,
  conversion_rate: s.sessions.size > 0 ? ((s.orders / s.sessions.size) * 100).toFixed(1) + '%' : '0%'
})).sort((a, b) => b.orders - a.orders);

// 2. Hourly distribution
const hourlyOrders = new Array(24).fill(0);
orders.forEach(o => {
  const h = new Date(o.createdAt || o.created_at).getHours();
  hourlyOrders[h]++;
});
const peakHour = hourlyOrders.indexOf(Math.max(...hourlyOrders));
const deadHours = hourlyOrders.map((v, i) => v === 0 ? i : null).filter(h => h !== null);

// 3. Drop-off analysis
const funnelStages = { view: 0, click: 0, add_to_cart: 0, checkout: 0, order_confirmed: 0 };
events.forEach(e => {
  const t = e.event_type || 'view';
  if (funnelStages.hasOwnProperty(t)) funnelStages[t]++;
});

const dropOffs = [];
const stageNames = Object.keys(funnelStages);
for (let i = 1; i < stageNames.length; i++) {
  const prev = funnelStages[stageNames[i-1]];
  const curr = funnelStages[stageNames[i]];
  if (prev > 0 && curr < prev) {
    dropOffs.push({
      from: stageNames[i-1],
      to: stageNames[i],
      drop_rate: ((1 - curr/prev) * 100).toFixed(1) + '%'
    });
  }
}

// 4. Campaign attribution
const campaignPerf = {};
events.filter(e => e.metadata_json?.campaign_id).forEach(e => {
  const cid = e.metadata_json.campaign_id;
  if (!campaignPerf[cid]) campaignPerf[cid] = { views: 0, conversions: 0 };
  campaignPerf[cid].views++;
  if (e.event_type === 'order_confirmed' || e.event_type === 'purchase') campaignPerf[cid].conversions++;
});

return { json: {
  analysis_period: '24h',
  analysis_time: new Date().toISOString(),
  total_funnel_events: events.length,
  total_orders: orders.length,
  channel_conversion: channelConversion,
  peak_hour: peakHour,
  dead_hours: deadHours,
  hourly_distribution: hourlyOrders,
  funnel_stages: funnelStages,
  drop_offs: dropOffs,
  campaign_performance: campaignPerf,
  best_channel: channelConversion.length > 0 ? channelConversion[0].channel : 'whatsapp'
}};

const llmResponse = $json.message?.content || $json.response || '{}';
const aggregated = $node['Aggregate Funnel Intelligence'].json;

// Try to parse LLM JSON response
let learnings = {};
try {
  // Extract JSON from potential markdown code block
  const jsonMatch = llmResponse.match(/```json?\s*([\s\S]*?)```/) || [null, llmResponse];
  learnings = JSON.parse(jsonMatch[1].trim());
} catch (e) {
  // Fallback: derive learnings from raw data
  learnings = {
    best_channel: aggregated.best_channel || 'whatsapp',
    peak_hours: [aggregated.peak_hour],
    worst_drop_off: aggregated.drop_offs.length > 0 ? `${aggregated.drop_offs[0].from} → ${aggregated.drop_offs[0].to} (${aggregated.drop_offs[0].drop_rate})` : 'none',
    recommended_actions: ['Améliorer le parcours de commande', 'Envoyer des promos aux heures de pointe', 'Relancer les paniers abandonnés'],
    upsell_timing: 'before_confirm',
    campaign_score: 50
  };
}

return { json: {
  data: {
    learnings_json: learnings,
    raw_stats: {
      total_events: aggregated.total_funnel_events,
      total_orders: aggregated.total_orders,
      channels: aggregated.channel_conversion,
      peak_hour: aggregated.peak_hour,
      drop_offs: aggregated.drop_offs
    },
    generated_at: new Date().toISOString(),
    model: $env.LLM_MODEL || 'llama3.1',
    llm_raw: llmResponse.substring(0, 500)
  }
}};
